import{_ as o,a,c as t,ac as s}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第四册：流利英语 · 综合复习与自测 · 第45–48课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第四册：流利英语 · 综合复习与自测 · 第45–48课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-4/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第四册：流利英语 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 综合复习与自测 · 第34–44课","link":"/life/english/new-concept/book-4/review-part-04"},"next":{"text":"第四册：流利英语 · 单元 1：从观察到判断","link":"/life/english/new-concept/book-4/unit-01/overview"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 综合复习与自测 · 第34–44课","link":"/life/english/new-concept/book-4/review-part-04"},"next":{"text":"第四册：流利英语 · 单元 1：从观察到判断","link":"/life/english/new-concept/book-4/unit-01/overview"}},"headers":[],"relativePath":"life/english/new-concept/book-4/review-part-05.md","filePath":"life/english/new-concept/book-4/review-part-05.md"}'),r={name:"life/english/new-concept/book-4/review-part-05.md"};function n(i,e,l,h,p,c){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="第四册-流利英语-·-综合复习与自测-·-第45–48课" tabindex="-1">第四册：流利英语 · 综合复习与自测 · 第45–48课 <a class="header-anchor" href="#第四册-流利英语-·-综合复习与自测-·-第45–48课" aria-label="Permalink to &quot;第四册：流利英语 · 综合复习与自测 · 第45–48课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-45-·-no-more-than-与-not-more-than" tabindex="-1">Lesson 45 · no more than 与 not more than <a class="header-anchor" href="#lesson-45-·-no-more-than-与-not-more-than" aria-label="Permalink to &quot;Lesson 45 · no more than 与 not more than {#lesson-45-·-no-more-than-与-not-more-than}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The summary contained no more than three pages, yet it raised questions the committee had overlooked.</p><h3 id="练习-1-44" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-44" aria-label="Permalink to &quot;练习 1 {#练习-1-44}&quot;">​</a></h3><p>not more than 10 是否允许恰好10？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 允许。</p><p><strong>解析：</strong> 意思是不超过10。</p></details><p><strong>表达迁移：</strong> 用三句评论一份虚构科学摘要：篇幅、提出的问题、社会决策还需要什么。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The summary contains no more than three pages. It explains a technical possibility but leaves its wider consequences open. Any public decision would also need discussion of costs, responsibilities and competing aims.</p><p>以少量文字与广泛影响形成对照，再区分技术可能性与公共判断，不把科学能力直接等同于社会选择。</p></details><p><a href="/life/english/new-concept/book-4/unit-06/lesson-045">回看本课</a></p><h2 id="lesson-46-·-would-rather-与-prefer-的补语" tabindex="-1">Lesson 46 · would rather 与 prefer 的补语 <a class="header-anchor" href="#lesson-46-·-would-rather-与-prefer-的补语" aria-label="Permalink to &quot;Lesson 46 · would rather 与 prefer 的补语 {#lesson-46-·-would-rather-与-prefer-的补语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I would rather repair an old radio than buy another one.</p><h3 id="练习-1-45" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-45" aria-label="Permalink to &quot;练习 1 {#练习-1-45}&quot;">​</a></h3><p>填空：She prefers drawing ___ collecting stamps.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> prefer doing A to doing B。</p></details><p><strong>表达迁移：</strong> 用三句介绍一种不以成绩为目的的爱好，包含偏好、过程和个人价值。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I would rather make a small wooden box than watch another series. Measuring and shaping the pieces requires my full attention. I enjoy the activity for its own sake, even when the result is imperfect.</p><p>选择结构引入爱好，具体过程说明体验，让步句保留不完美作品的价值。</p></details><p><a href="/life/english/new-concept/book-4/unit-06/lesson-046">回看本课</a></p><h2 id="lesson-47-·-篇章指代与-this-概括名词" tabindex="-1">Lesson 47 · 篇章指代与 this + 概括名词 <a class="header-anchor" href="#lesson-47-·-篇章指代与-this-概括名词" aria-label="Permalink to &quot;Lesson 47 · 篇章指代与 this + 概括名词 {#lesson-47-·-篇章指代与-this-概括名词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We expected the trip to remove every worry. That expectation proved unrealistic.</p><h3 id="练习-1-46" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-46" aria-label="Permalink to &quot;练习 1 {#练习-1-46}&quot;">​</a></h3><p>示例中的 That expectation 指什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 旅行能消除所有烦恼的期待。</p><p><strong>解析：</strong> 概括名词回指前句整项想法。</p></details><p><strong>表达迁移：</strong> 写三句露营反思：出发前期待、实际体验、用概括名词连接认识。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I expected camping to be no more than a cheaper holiday. Sharing a table with strangers changed my view. That experience made conversation, rather than cost alone, the most memorable part of the trip.</p><p>露营场景呼应本课主题；That experience 明确回指与陌生人同桌交流，比较结构说明动机和收获不止费用。</p></details><p><a href="/life/english/new-concept/book-4/unit-06/lesson-047">回看本课</a></p><h2 id="lesson-48-·-决策段落中的-however、therefore-与条件" tabindex="-1">Lesson 48 · 决策段落中的 however、therefore 与条件 <a class="header-anchor" href="#lesson-48-·-决策段落中的-however、therefore-与条件" aria-label="Permalink to &quot;Lesson 48 · 决策段落中的 however、therefore 与条件 {#lesson-48-·-决策段落中的-however、therefore-与条件}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The two plans serve different objectives; therefore, comparing returns alone would be misleading.</p><h3 id="练习-1-47" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-47" aria-label="Permalink to &quot;练习 1 {#练习-1-47}&quot;">​</a></h3><p>改标点：The assumptions differ, therefore the results are not directly comparable.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The assumptions differ; therefore, the results are not directly comparable.</p><p><strong>解析：</strong> therefore 不是并列连词，不能仅用逗号连接独立句。</p></details><p><strong>表达迁移：</strong> 写三句虚构方案评估，不给投资建议：明确目标、指出一种不确定性、说明比较原则。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The first step is to define the purpose of the hypothetical portfolio. Future outcomes remain uncertain, even when the choices are spread across several categories. Therefore, any comparison should consider assumptions and constraints as well as possible returns.</p><p>按目标、不确定性、评价原则展开；未承诺分散一定获利，也未给出个人买卖建议。</p></details><p><a href="/life/english/new-concept/book-4/unit-06/lesson-048">回看本课</a></p>',36)])])}const u=o(r,[["render",n]]);export{m as __pageData,u as default};
